UPDATE tools SET long_description = E'TimeCamp, c''est outil de suivi du temps et rapports pour la productivité. À partir de 20€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue TimeCamp : spécialisé en time tracking, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'TimeCamp is time tracking and reporting tool for productivity. Starting at €20/month. Most relevant for B2B consultants and SaaS founders.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'timecamp';
UPDATE tools SET long_description = E'Gemini, c''est l''IA de Google qui double ses performances tous les 3 mois. À partir de 20€/mois. Particulièrement pertinent pour les consultants B2B et les créateurs de contenu.\n\nCe qui distingue Gemini : raisonnement avancé : 77.1% sur ARC-AGI-2 (double de Gemini 3 Pro). Ajoutez à ça creative coding : génération de code complexe (3D, animations, SVG), et pricing compétitif : $2/$12/M tokens (similaire à Claude). Pour les usages intensifs : intégration Google : Workspace, NotebookLM, Android Studio. Cas d''usage typique : creative coding : générer des animations SVG, interfaces 3D, designs interactifs. On l''utilise aussi pour raisonnement complexe : résoudre des problèmes logiques, patterns nouveaux. Gain de temps estimé : 7h/mois pour un usage régulier.\n\nÀ garder si : besoin de raisonnement complexe (ARC-AGI-2 : 77.1%) ou creative coding et design génératif. À éviter si : préférence pour une IA plus mature (Claude/ChatGPT) ou besoin de stabilité (Gemini 3.1 Pro en preview). Point de friction : preview : pas encore en disponibilité générale (moins stable). Dès que vous avez besoin de raisonnement logique avancé ou de creative coding.', long_description_en = E'Gemini is google''s AI that doubles its performance every 3 months. Starting at €20/month. Most relevant for B2B consultants and content creators.\n\nEstimated time saving: 7h/month with regular use.' WHERE slug = 'gemini';
UPDATE tools SET long_description = E'Adobe Illustrator, c''est le standard du design vectoriel et de l''illustration. À partir de 26.21€/mois. Particulièrement pertinent pour les graphiste-da et les illustrateur.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : création de logos, chartes graphiques ou print et identité visuelle. À éviter si : uI/UX uniquement — Figma est plus adapté. Dès que vous créez des éléments vectoriels pour du print ou branding. Alternative gratuite à considérer : affinity-designer.', long_description_en = E'Adobe Illustrator is the standard for vector design and illustration. Starting at €26.21/month. Most relevant for graphiste-da and illustrateur.\n\nEstimated time saving: 5h/month with regular use.\n\nFree alternative worth considering: affinity-designer.' WHERE slug = 'adobe-illustrator';
UPDATE tools SET long_description = E'Adobe After Effects, c''est le standard du motion design et des effets visuels. À partir de 26.21€/mois. Particulièrement pertinent pour les motion-video.\n\nGain de temps estimé : 10h/mois pour un usage régulier.\n\nÀ garder si : motion design, génériques, animations complexes. À éviter si : animation simple — Rive ou Lottie suffisent. Dès que vous créez des animations frame par frame.', long_description_en = E'Adobe After Effects is the standard for motion design and visual effects. Starting at €26.21/month. Most relevant for motion-video.\n\nEstimated time saving: 10h/month with regular use.' WHERE slug = 'adobe-after-effects';
UPDATE tools SET long_description = E'Adobe Creative Cloud, c''est la suite complète : Photoshop, Illustrator, Premiere, After Effects, Lightroom et +20 apps. À partir de 78.65€/mois. Particulièrement pertinent pour les graphiste-da et les motion-video.\n\nGain de temps estimé : 15h/mois pour un usage régulier.\n\nÀ garder si : vous utilisez 3+ apps Adobe régulièrement ou production professionnelle tous azimuts. À éviter si : 1-2 apps seulement — prenez un plan app unique. Rentable dès que vous utilisez Photoshop + Premiere + une autre app.', long_description_en = E'Adobe Creative Cloud is the complete suite: Photoshop, Illustrator, Premiere, After Effects, Lightroom and 20+ apps. Starting at €78.65/month. Most relevant for graphiste-da and motion-video.\n\nEstimated time saving: 15h/month with regular use.' WHERE slug = 'adobe-cc';
UPDATE tools SET long_description = E'Capture One, c''est le logiciel de retouche RAW préféré des photographes professionnels. À partir de 24€/mois. Particulièrement pertinent pour les photographe.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : photographie studio, mode, portrait haut de gamme. À éviter si : workflow déjà sur Lightroom — migration coûteuse. Rentable si vous facturez des shootings à 500€+ régulièrement.', long_description_en = E'Capture One is the RAW editing software preferred by professional photographers. Starting at €24/month. Most relevant for photographe.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'capture-one';
UPDATE tools SET long_description = E'Vercel, c''est la plateforme de déploiement frontend la plus rapide. À partir de 17.32€/mois. Particulièrement pertinent pour les developpeur-solo et les ai-builder.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : deploy frontend Next.js/React. À éviter si : backend lourd — Railway ou Fly.io plus adaptés. Gratuit donc toujours pertinent pour le frontend.', long_description_en = E'Vercel is the fastest frontend deployment platform. Starting at €17.32/month. Most relevant for solo developers and ai-builder.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'vercel';
UPDATE tools SET long_description = E'Flow (aescripts), c''est le plugin d''animation de courbes le plus populaire pour After Effects. À partir de 8€/mois. Particulièrement pertinent pour les motion-video.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : motion design intensif sur After Effects. À éviter si : usage occasionnel — courbes natives suffisent. Rentable dès 10h/mois sur After Effects.', long_description_en = E'Flow (aescripts) is the most popular curve animation plugin for After Effects. Starting at €8/month. Most relevant for motion-video.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'aescripts-flow';
UPDATE tools SET long_description = E'Intercom, c''est la plateforme de support client et d''onboarding pour SaaS. À partir de 64.09€/mois. Particulièrement pertinent pour les fondateurs SaaS et les manager-dsi.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : saaS avec base utilisateurs active et besoin de support. À éviter si : early stage — Crisp ou Tawk.to gratuits suffisent. Rentable à partir de 500 utilisateurs actifs. Alternative gratuite à considérer : crisp.', long_description_en = E'Intercom is the customer support and onboarding platform for SaaS. Starting at €64.09/month. Most relevant for SaaS founders and manager-dsi.\n\nEstimated time saving: 5h/month with regular use.\n\nFree alternative worth considering: crisp.' WHERE slug = 'intercom';
UPDATE tools SET long_description = E'Amplitude, c''est la plateforme d''analytics produit pour comprendre le comportement utilisateur. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les fondateurs SaaS et les product-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : produit digital avec analyse comportementale fine. À éviter si : simple website — Plausible suffit. Gratuit jusqu à 50k events — toujours pertinent au démarrage. Si le budget le permet, posthog est souvent une meilleure option.', long_description_en = E'Amplitude is the product analytics platform to understand user behaviour. Core features are free, with paid plans for advanced use. Most relevant for SaaS founders and product-manager.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, posthog is often a better fit.' WHERE slug = 'amplitude';
UPDATE tools SET long_description = E'Kling AI, c''est génération vidéo IA réaliste jusqu''à 2 minutes. Alternative sérieuse à Runway. À partir de 8.66€/mois. Particulièrement pertinent pour les motion-video et les créateurs de contenu.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : vidéos longues (>10s) avec réalisme cinématique. À éviter si : runway ou Pika déjà en place — triplon génération vidéo. À tester en gratuit avant de payer. Si le budget le permet, runway est souvent une meilleure option.', long_description_en = E'Kling AI is realistic AI video generation up to 2 minutes. A serious Runway alternative. Starting at €8.66/month. Most relevant for motion-video and content creators.\n\nEstimated time saving: 6h/month with regular use.\n\nIf budget allows, runway is often a better fit.' WHERE slug = 'kling-ai';
UPDATE tools SET long_description = E'Magnific AI, c''est upscaling IA d''images avec ajout de détails hallucinés. Résultats uniques. À partir de 33.78€/mois. Particulièrement pertinent pour les photographe et les graphiste-da.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : upscaling créatif haute résolution pour print ou portfolio. À éviter si : usage vidéo — Topaz Video AI est plus adapté et moins cher. Rentable si vous vendez des tirages grand format régulièrement. Si le budget le permet, topaz-video-ai est souvent une meilleure option.', long_description_en = E'Magnific AI is aI image upscaling with hallucinated detail addition. Unique results. Starting at €33.78/month. Most relevant for photographe and graphiste-da.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, topaz-video-ai is often a better fit.' WHERE slug = 'magnific-ai';
UPDATE tools SET long_description = E'Udio, c''est génération musicale IA de haute qualité à partir d''un prompt texte. À partir de 8.66€/mois. Particulièrement pertinent pour les motion-video et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : création de jingles, ambiances ou musiques pour vos vidéos. À éviter si : suno déjà dans le stack — doublon génération musicale. Rentable dès 3 projets vidéo avec musique originale par mois.', long_description_en = E'Udio is high-quality AI music generation from a text prompt. Starting at €8.66/month. Most relevant for motion-video and content creators.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'udio';
UPDATE tools SET long_description = E'Descript, c''est édition audio/vidéo par le texte. Transcription, suppression de silences, overdub IA. À partir de 10.39€/mois. Particulièrement pertinent pour les podcasteur et les créateurs de contenu.\n\nGain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : podcast, interviews, cours en ligne — gain de temps massif. À éviter si : montage vidéo long format — Premiere ou DaVinci plus adaptés. Rentable dès 2 épisodes podcast ou vidéos par mois.', long_description_en = E'Descript is text-based audio/video editing. Transcription, silence removal, AI overdub. Starting at €10.39/month. Most relevant for podcasteur and content creators.\n\nEstimated time saving: 8h/month with regular use.' WHERE slug = 'descript';
UPDATE tools SET long_description = E'Bolt.new, c''est génération d''applications web complètes depuis un prompt. Alternative à Lovable. À partir de 17.32€/mois. Particulièrement pertinent pour les developpeur-solo et les ai-builder.\n\nGain de temps estimé : 12h/mois pour un usage régulier.\n\nÀ garder si : prototypage rapide sans backend complexe. À éviter si : lovable ou Cursor déjà en place — fort doublon. Rentable dès le premier prototype validé par un client.', long_description_en = E'Bolt.new is full web app generation from a prompt. Alternative to Lovable. Starting at €17.32/month. Most relevant for solo developers and ai-builder.\n\nEstimated time saving: 12h/month with regular use.' WHERE slug = 'bolt-new';
UPDATE tools SET long_description = E'Replit, c''est iDE en ligne avec IA intégrée, hébergement et collaboration en temps réel. À partir de 17.32€/mois. Particulièrement pertinent pour les developpeur-solo et les ai-builder.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : formation au code, prototypage rapide en ligne. À éviter si : cursor ou Bolt déjà en place. Surtout utile pour enseigner le code ou prototyper sur iPad. Si le budget le permet, cursor est souvent une meilleure option.', long_description_en = E'Replit is online IDE with built-in AI, hosting, and real-time collaboration. Starting at €17.32/month. Most relevant for solo developers and ai-builder.\n\nEstimated time saving: 6h/month with regular use.\n\nIf budget allows, cursor is often a better fit.' WHERE slug = 'replit';
UPDATE tools SET long_description = E'Stable Diffusion, c''est génération d''images IA open source — contrôle total, hébergement local possible. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les graphiste-da et les illustrateur.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : fine-tuning sur votre style, génération locale sans cloud. À éviter si : midjourney ou Firefly suffisent pour 95% des usages créatifs. Pertinent uniquement si vous avez un GPU dédié ou des besoins de volume.', long_description_en = E'Stable Diffusion is open-source AI image generation — full control, local hosting possible. Core features are free, with paid plans for advanced use. Most relevant for graphiste-da and illustrateur.\n\nEstimated time saving: 6h/month with regular use.' WHERE slug = 'stable-diffusion';
UPDATE tools SET long_description = E'Mem AI, c''est note-taking IA avec mémoire contextuelle — vos notes se connectent automatiquement. À partir de 12.12€/mois. Particulièrement pertinent pour les consultants B2B et les newslettiste-auteur.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : chercheur, auteur avec volume massif de notes à connecter. À éviter si : notion ou Obsidian déjà en place. Niche — pertinent surtout pour les knowledge workers intensifs. Si le budget le permet, notion est souvent une meilleure option.', long_description_en = E'Mem AI is aI note-taking with contextual memory — your notes connect automatically. Starting at €12.12/month. Most relevant for B2B consultants and newslettiste-auteur.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, notion is often a better fit.' WHERE slug = 'mem-ai';
UPDATE tools SET long_description = E'Flux (Black Forest Labs), c''est modèle de génération d''images IA open source — qualité supérieure à Stable Diffusion. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les graphiste-da et les illustrateur.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : génération haute qualité via API, fine-tuning possible. À éviter si : midjourney ou Leonardo suffisent pour les usages standards. Pertinent si vous construisez des pipelines IA custom.', long_description_en = E'Flux (Black Forest Labs) is open-source AI image generation model — higher quality than Stable Diffusion. Core features are free, with paid plans for advanced use. Most relevant for graphiste-da and illustrateur.\n\nEstimated time saving: 5h/month with regular use.' WHERE slug = 'flux';
UPDATE tools SET long_description = E'Stark, c''est vérification de l''accessibilité (contrastes, daltonisme) directement dans Figma. À partir de 6.06€/mois. Particulièrement pertinent pour les ux-ui et les graphiste-da.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : projets avec contraintes d''accessibilité WCAG. À éviter si : pas de contrainte accessibilité — version gratuite suffit. Gratuit pour les vérifications de base — toujours utile.', long_description_en = E'Stark is accessibility checking (contrast, colour blindness) directly in Figma. Starting at €6.06/month. Most relevant for ux-ui and graphiste-da.\n\nEstimated time saving: 2h/month with regular use.' WHERE slug = 'figma-stark';
UPDATE tools SET long_description = E'Spotify for Podcasters, c''est hébergement et distribution podcast 100% gratuit par Spotify. L''outil est entièrement gratuit. Particulièrement pertinent pour les podcasteur et les créateurs de contenu.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : démarrage podcast, budget zéro. À éviter si : analytics avancés ou monétisation — Buzzsprout plus adapté. Gratuit — toujours le bon choix pour démarrer. Si le budget le permet, buzzsprout est souvent une meilleure option.', long_description_en = E'Spotify for Podcasters is 100% free podcast hosting and distribution by Spotify. It''s completely free. Most relevant for podcasteur and content creators.\n\nEstimated time saving: 2h/month with regular use.\n\nIf budget allows, buzzsprout is often a better fit.' WHERE slug = 'anchor-spotify';
UPDATE tools SET long_description = E'Podbean, c''est hébergement podcast avec monétisation intégrée (dynamic ads, abonnements). À partir de 7.79€/mois. Particulièrement pertinent pour les podcasteur.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : monétisation via dynamic ads ou abonnements auditeurs. À éviter si : buzzsprout ou Anchor déjà en place — doublon hébergement. Pertinent uniquement si la monétisation directe est votre priorité. Alternative gratuite à considérer : anchor-spotify.', long_description_en = E'Podbean is podcast hosting with built-in monetisation (dynamic ads, subscriptions). Starting at €7.79/month. Most relevant for podcasteur.\n\nEstimated time saving: 2h/month with regular use.\n\nFree alternative worth considering: anchor-spotify.' WHERE slug = 'podbean';
UPDATE tools SET long_description = E'TubeBuddy, c''est extension YouTube pour optimiser le SEO, les tags et la performance de vos vidéos. À partir de 4.33€/mois. Particulièrement pertinent pour les créateurs de contenu.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : youTube comme canal principal avec SEO vidéo actif. À éviter si : vidIQ déjà en place — doublon SEO YouTube. Rentable dès 500 abonnés YouTube.', long_description_en = E'TubeBuddy is youTube extension to optimise SEO, tags, and video performance. Starting at €4.33/month. Most relevant for content creators.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'tubebody';
UPDATE tools SET long_description = E'Substack, c''est plateforme newsletter et blog avec monétisation intégrée. Zéro friction. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les newslettiste-auteur et les créateurs de contenu.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : démarrage newsletter, communauté déjà sur Substack. À éviter si : beehiiv si vous monétisez — 0% commission vs 10%. Gratuit — pertinent pour démarrer sans engagement. Si le budget le permet, beehiiv est souvent une meilleure option.', long_description_en = E'Substack is newsletter and blog platform with built-in monetisation. Zero friction. Core features are free, with paid plans for advanced use. Most relevant for newslettiste-auteur and content creators.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, beehiiv is often a better fit.' WHERE slug = 'substack';
UPDATE tools SET long_description = E'Lever, c''est aTS (Applicant Tracking System) moderne pour équipes de recrutement. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les rh-recruteur et les manager-dsi.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : volume de recrutement régulier, équipe RH dédiée. À éviter si : moins de 10 recrutements/an — Notion + Airtable suffisent. Rentable à partir de 20 recrutements par an.', long_description_en = E'Lever is modern ATS (Applicant Tracking System) for recruitment teams. Core features are free, with paid plans for advanced use. Most relevant for rh-recruteur and manager-dsi.\n\nEstimated time saving: 6h/month with regular use.' WHERE slug = 'lever';
UPDATE tools SET long_description = E'Workable, c''est aTS tout-en-un avec sourcing IA, job boards et onboarding. À partir de 163.68€/mois. Particulièrement pertinent pour les rh-recruteur et les manager-dsi.\n\nGain de temps estimé : 7h/mois pour un usage régulier.\n\nÀ garder si : rH avec sourcing actif et onboarding structuré. À éviter si : lever déjà en place — doublon ATS. Rentable à partir de 5 postes ouverts simultanément.', long_description_en = E'Workable is all-in-one ATS with AI sourcing, job boards, and onboarding. Starting at €163.68/month. Most relevant for rh-recruteur and manager-dsi.\n\nEstimated time saving: 7h/month with regular use.' WHERE slug = 'workable';
UPDATE tools SET long_description = E'Thinkific, c''est plateforme de création de cours en ligne avec branding personnalisé. À partir de 31.18€/mois. Particulièrement pertinent pour les coach-formateur.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : formations certifiantes avec besoin de branding fort. À éviter si : kajabi ou Podia déjà en place — doublon LMS. Rentable dès 2 cours actifs avec 10+ élèves. Si le budget le permet, kajabi est souvent une meilleure option.', long_description_en = E'Thinkific is online course creation platform with custom branding. Starting at €31.18/month. Most relevant for coach-formateur.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, kajabi is often a better fit.' WHERE slug = 'thinkific';
UPDATE tools SET long_description = E'Circle, c''est la plateforme de communauté en ligne pour créateurs et formateurs. À partir de 42.44€/mois. Particulièrement pertinent pour les coach-formateur et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : communauté payante active avec cours et événements. À éviter si : kajabi déjà en place — doublon communauté/cours. Rentable dès 50 membres payants.', long_description_en = E'Circle is the online community platform for creators and educators. Starting at €42.44/month. Most relevant for coach-formateur and content creators.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'circle';

